def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "navigate_inside": And([
            self.robot_at(self.doorway),
            Not(self.robot_has(self.contribution_container)),
            Not(self.verbal_cue_played),
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
